%% ============================================================
%% Architecture-Level Ablation
%% ============================================================

\vspace{-4pt}
\subsection{Architecture-Level Ablation}
\label{sec:arch_results}

\paragraph{Critic convergence in pure imagination.}
\looseness=-1 Across all dual-critic configurations ($n{=}7$), critics converge ($\rho > 0.999$) with pessimism at only 3--4\% of the independent-critic bound, rendering standard pessimistic value estimation ineffective in pure imagination.

\paragraph{Wide dual-critic: the sole partial success.}
\looseness=-1 A $2{\times}2$ factorial separates two mechanisms: narrow dual-critic (min, ${\sim}1.2$M) recovers from CIVO (${\sim}16$--$19\times$ ratio reduction) but does not prevent onset; wide dual-critic (min $+$ ${\sim}2.4$M) achieves NVE $\leq 1.4\times$ in 3/4 seeds (3/3 Walker, 0/1 Cheetah), the strongest result across all levels (Table~\ref{tab:intervention_hierarchy}). Wide single (0/2) confirms both components are necessary. Cross-environment transfer is limited (Appendix~\ref{sec:dual_critic_appendix}).
